  );
}

import { useState } from "react";

type RegistrationValues = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
};

function RegistrationFields() {
  const [formData, setFormData] = useState<RegistrationValues>({
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
  });

  function handleChange(event: React.ChangeEvent<HTMLInputElement>) {
    const { name, value } = event.currentTarget;
    const field = name as keyof RegistrationValues;
    setFormData((current) => ({ ...current, [field]: value }));
  }

  return (
    <>
      <label htmlFor="name">Name</label>
      <input id="name" name="name" value={formData.name} onChange={handleChange} />
      <label htmlFor="email">Email</label>
      <input id="email" name="email" value={formData.email} onChange={handleChange} />
      <label htmlFor="password">Password</label>
      <input id="password" name="password" type="password" value={formData.password} onChange={handleChange} />
      <label htmlFor="confirmPassword">Confirm password</label>
      <input id="confirmPassword" name="confirmPassword" type="password" value={formData.confirmPassword} onChange={handleChange} />
    </>
  );
}

type FormValues = { email: string; password: string };

function validate(values: FormValues) {
  const errors: Partial<Record<keyof FormValues, string>> = {};
  if (!values.email.includes("@")) errors.email = "Enter a valid email address.";
  if (values.password.length < 8) errors.password = "Use at least 8 characters.";
  return errors;
}

type RegistrationValues = {
  email: string;
  password: string;
  confirmPassword: string;
};

type FieldErrors = Partial<Record<keyof RegistrationValues, string>>;

function validateRegistration(values: RegistrationValues): FieldErrors {
  const errors: FieldErrors = {};
  if (!values.email.includes("@")) {
    errors.email = "Enter a valid email address.";
  }
  if (values.password.length < 8) {
    errors.password = "Use at least eight characters.";
  }
  if (values.confirmPassword !== values.password) {
    errors.confirmPassword = "Passwords do not match.";
  }
  return errors;
}

