import { useForm } from "react-hook-form";

type RegistrationValues = { email: string; password: string };

function RegistrationForm() {
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<RegistrationValues>({ mode: "onBlur" });

  async function onSubmit(data: RegistrationValues) {
    // Replace this log with your application's async request.
    console.log("Validated values", data);
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="email">Email</label>
      <input id="email" type="email"
        aria-invalid={Boolean(errors.email)}
        aria-describedby={errors.email ? "email-error" : undefined}
        {...register("email", {
          required: "Email is required",
          pattern: { value: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: "Enter a valid email." },
        })}
      />
      {errors.email && <p id="email-error">{errors.email.message}</p>}
      <label htmlFor="password">Password</label>
      <input id="password" type="password"
        aria-invalid={Boolean(errors.password)}
        aria-describedby={errors.password ? "password-error" : undefined}
        {...register("password", {
          required: "Password is required",
          minLength: { value: 8, message: "Use at least 8 characters." },
        })}
      />
      {errors.password && <p id="password-error">{errors.password.message}</p>}
      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Submitting..." : "Create account"}
      </button>
    </form>
  );
}

